window.SEARCH_INDEX=[{"t": "Can a peaceful protest lead to detention?", "u": "article-peaceful-protest.html", "k": "Article", "d": "Peaceful assembly, restrictions and detention safeguards."}, {"t": "Freelancers and contracts: what should you check?", "u": "article-freelancer-contracts.html", "k": "Article", "d": "Scope, payment, ownership, confidentiality and disputes."}, {"t": "When can a social media post become evidence?", "u": "article-digital-evidence.html", "k": "Article", "d": "Electronic records, authenticity and context."}, {"t": "Maneka Gandhi v. Union of India, (1978) 1 SCC 248", "u": "case-law.html#case-maneka-gandhi-v-union-of-india", "k": "Case note", "d": "Constitutional. Fairness is part of Article 21, and arbitrary state action is open to challenge. How the principle works for a given statute still depends on its terms and the facts."}, {"t": "Shreya Singhal v. Union of India, (2015) 5 SCC 1", "u": "case-law.html#case-shreya-singhal-v-union-of-india", "k": "Case note", "d": "Constitutional. Vague criminal laws on speech can be struck down. Online expression receives constitutional protection, subject to restrictions that fit within Article 19(2)."}, {"t": "Justice K.S. Puttaswamy (Retd.) v. Union of India, (2017) 10 SCC 1", "u": "case-law.html#case-justice-k-s-puttaswamy-retd-v-union-of-india", "k": "Case note", "d": "Constitutional. Privacy is a fundamental right. The decision does not decide every privacy dispute, and later cases apply its tests to specific laws."}, {"t": "Kesavananda Bharati v. State of Kerala, (1973) 4 SCC 225", "u": "case-law.html#case-kesavananda-bharati-v-state-of-kerala", "k": "Case note", "d": "Constitutional. The basic structure doctrine. The list of basic features has been developed case by case since."}, {"t": "Minerva Mills Ltd. v. Union of India, (1980) 3 SCC 625", "u": "case-law.html#case-minerva-mills-ltd-v-union-of-india", "k": "Case note", "d": "Constitutional. Parliament cannot give itself unlimited amending power. Fundamental Rights and Directive Principles must be read in harmony."}, {"t": "S.R. Bommai v. Union of India, (1994) 3 SCC 1", "u": "case-law.html#case-s-r-bommai-v-union-of-india", "k": "Case note", "d": "Constitutional. Article 356 is a limited, reviewable power. Federalism and secularism are basic features of the Constitution."}, {"t": "Indra Sawhney v. Union of India, 1992 Supp (3) SCC 217", "u": "case-law.html#case-indra-sawhney-v-union-of-india", "k": "Case note", "d": "Constitutional. Sets the basic framework for OBC reservation. Later amendments and cases have addressed other questions, so check the current law."}, {"t": "Navtej Singh Johar v. Union of India, (2018) 10 SCC 1", "u": "case-law.html#case-navtej-singh-johar-v-union-of-india", "k": "Case note", "d": "Constitutional. Constitutional morality, not social morality, guides the Court. Consensual same-sex conduct between adults is not a crime."}, {"t": "Joseph Shine v. Union of India, (2019) 3 SCC 39", "u": "case-law.html#case-joseph-shine-v-union-of-india", "k": "Case note", "d": "Constitutional. Adultery is no longer a criminal offence. It can still be relevant in civil matters such as divorce."}, {"t": "Vishaka v. State of Rajasthan, (1997) 6 SCC 241", "u": "case-law.html#case-vishaka-v-state-of-rajasthan", "k": "Case note", "d": "Constitutional. Courts can fill a legislative gap. The guidelines were later replaced by the Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013."}, {"t": "Olga Tellis v. Bombay Municipal Corporation, (1985) 3 SCC 545", "u": "case-law.html#case-olga-tellis-v-bombay-municipal-corporation", "k": "Case note", "d": "Constitutional. Livelihood is protected by Article 21. Eviction must follow a fair procedure, but the case does not create a right to occupy public land."}, {"t": "Bachan Singh v. State of Punjab, (1980) 2 SCC 684", "u": "case-law.html#case-bachan-singh-v-state-of-punjab", "k": "Case note", "d": "Criminal. Life imprisonment is the rule and death the exception, decided case by case. Later cases keep refining how the test is applied."}, {"t": "Lalita Kumari v. Government of Uttar Pradesh, (2014) 2 SCC 1", "u": "case-law.html#case-lalita-kumari-v-government-of-uttar-pradesh", "k": "Case note", "d": "Criminal. Police cannot refuse to register an FIR where a cognizable offence is disclosed. Section 154 CrPC is now Section 173 of the BNSS, so check the current text."}, {"t": "Arnesh Kumar v. State of Bihar, (2014) 8 SCC 273", "u": "case-law.html#case-arnesh-kumar-v-state-of-bihar", "k": "Case note", "d": "Criminal. Arrest needs recorded justification. The CrPC has since been replaced by the Bharatiya Nagarik Suraksha Sanhita, 2023, so check the corresponding provisions now in force."}, {"t": "Carlill v. Carbolic Smoke Ball Co., [1893] 1 QB 256", "u": "case-law.html#case-carlill-v-carbolic-smoke-ball-co", "k": "Case note", "d": "Contract. Leading case on unilateral offers and acceptance by performance. Section 8 of the Indian Contract Act, 1872 reflects the idea."}, {"t": "Mohori Bibee v. Dharmodas Ghose, (1903) ILR 30 Cal 539", "u": "case-law.html#case-mohori-bibee-v-dharmodas-ghose", "k": "Case note", "d": "Contract. A minor’s agreement is void in India. The case is a standard reference on capacity to contract."}, {"t": "Hadley v. Baxendale, (1854) 9 Exch 341", "u": "case-law.html#case-hadley-v-baxendale", "k": "Case note", "d": "Contract. Sets the remoteness rule for contract damages. Section 73 of the Indian Contract Act, 1872 follows a similar approach."}, {"t": "M.C. Mehta v. Union of India (Oleum Gas Leak), (1987) 1 SCC 395", "u": "case-law.html#case-m-c-mehta-v-union-of-india-oleum-gas-leak", "k": "Case note", "d": "Tort. India applies absolute liability for hazardous industries. It is a key case on environmental and industrial accidents."}, {"t": "Donoghue v. Stevenson, [1932] AC 562", "u": "case-law.html#case-donoghue-v-stevenson", "k": "Case note", "d": "Tort. Foundation of the modern law of negligence. Indian courts have referred to it when developing tort law."}, {"t": "Shankari Prasad Singh Deo v. Union of India, AIR 1951 SC 458", "u": "case-law.html#case-shankari-prasad-singh-deo-v-union-of-india", "k": "Case note", "d": "Constitutional. An early view that Parliament could amend Fundamental Rights. Later cases, ending with Kesavananda Bharati, limited this power through the basic structure doctrine."}, {"t": "A.K. Gopalan v. State of Madras, AIR 1950 SC 27", "u": "case-law.html#case-a-k-gopalan-v-state-of-madras", "k": "Case note", "d": "Constitutional. A narrow reading of Article 21 that was later displaced by Maneka Gandhi v. Union of India."}, {"t": "ADM Jabalpur v. Shivkant Shukla, (1976) 2 SCC 521", "u": "case-law.html#case-adm-jabalpur-v-shivkant-shukla", "k": "Case note", "d": "Constitutional. The decision was widely criticised. In Puttaswamy (2017) the Court said it was wrongly decided. The 44th Amendment now prevents suspension of Articles 20 and 21 in an Emergency."}, {"t": "E.P. Royappa v. State of Tamil Nadu, (1974) 4 SCC 3", "u": "case-law.html#case-e-p-royappa-v-state-of-tamil-nadu", "k": "Case note", "d": "Constitutional. The “arbitrariness” test for Article 14. Later cases used it to strike down both executive actions and laws."}, {"t": "Mithu v. State of Punjab, (1983) 2 SCC 277", "u": "case-law.html#case-mithu-v-state-of-punjab", "k": "Case note", "d": "Criminal. Courts need discretion in sentencing. Check how the BNS now treats similar situations."}, {"t": "Nandini Satpathy v. P.L. Dani, (1978) 2 SCC 424", "u": "case-law.html#case-nandini-satpathy-v-p-l-dani", "k": "Case note", "d": "Criminal. The right against self-incrimination applies at the investigation stage, not only in court."}, {"t": "Hussainara Khatoon v. State of Bihar, (1980) 1 SCC 81", "u": "case-law.html#case-hussainara-khatoon-v-state-of-bihar", "k": "Case note", "d": "Criminal. Speedy trial and free legal aid are part of Article 21, supported by Article 39A."}, {"t": "Siddharam Satlingappa Mhetre v. State of Maharashtra, (2011) 1 SCC 694", "u": "case-law.html#case-siddharam-satlingappa-mhetre-v-state-of-maharashtra", "k": "Case note", "d": "Criminal. Anticipatory bail is closely tied to liberty and is decided on the facts. It is now dealt with in Section 482 of the BNSS."}, {"t": "Balfour v. Balfour, [1919] 2 KB 571", "u": "case-law.html#case-balfour-v-balfour", "k": "Case note", "d": "Contract. Intention to create legal relations is needed for a contract. The presumption for domestic arrangements can be rebutted in some situations."}, {"t": "Satyabrata Ghose v. Mugneeram Bangur & Co., AIR 1954 SC 44", "u": "case-law.html#case-satyabrata-ghose-v-mugneeram-bangur-co", "k": "Case note", "d": "Contract. Section 56 is the Indian home of frustration. Mere hardship or delay is usually not enough, and the question is whether the foundation of the contract is destroyed."}, {"t": "Rylands v. Fletcher, (1868) LR 3 HL 330", "u": "case-law.html#case-rylands-v-fletcher", "k": "Case note", "d": "Tort. The rule of strict liability. India went further with absolute liability in M.C. Mehta v. Union of India."}, {"t": "Salomon v. A. Salomon & Co. Ltd., [1897] AC 22", "u": "case-law.html#case-salomon-v-a-salomon-co-ltd", "k": "Case note", "d": "Company. The foundation of separate legal personality. Courts lift the corporate veil only in limited situations."}, {"t": "Foss v. Harbottle, (1843) 2 Hare 461", "u": "case-law.html#case-foss-v-harbottle", "k": "Case note", "d": "Company. The proper plaintiff rule and the majority rule. Exceptions exist, for example where there is fraud on the minority."}, {"t": "Habeas Corpus", "u": "glossary.html#term-habeas-corpus", "k": "Glossary", "d": "Constitutional remedy. A writ used to require that a detained person be brought before a court so the legality of detention can be examined."}, {"t": "Mandamus", "u": "glossary.html#term-mandamus", "k": "Glossary", "d": "Constitutional remedy. A writ that directs a public authority to perform a public legal duty it has failed to perform. The word means “we command”."}, {"t": "Mens Rea", "u": "glossary.html#term-mens-rea", "k": "Glossary", "d": "Criminal law. Generally refers to the mental element of an offence. The required mental state depends on the particular offence and statute."}, {"t": "Cognizable Offence", "u": "glossary.html#term-cognizable-offence", "k": "Glossary", "d": "Criminal procedure. An offence for which the police can generally start an investigation and arrest without a warrant, as classified under the applicable procedural law."}, {"t": "Bail", "u": "glossary.html#term-bail", "k": "Glossary", "d": "Criminal procedure. The release of an accused person while a case is pending, usually on conditions. Rules and court discretion depend on the offence and the circumstances."}, {"t": "Prima Facie", "u": "glossary.html#term-prima-facie", "k": "Glossary", "d": "Evidence. Latin for “at first sight”. A prima facie case is one supported by enough evidence on its face to proceed unless it is rebutted."}, {"t": "Res Judicata", "u": "glossary.html#term-res-judicata", "k": "Glossary", "d": "Civil procedure. A principle that, subject to its legal requirements and exceptions, prevents a matter already finally decided between parties from being litigated again. In India, Section 11 of the Code of Civil Procedure, 1908 reflects it."}, {"t": "Locus Standi", "u": "glossary.html#term-locus-standi", "k": "Glossary", "d": "Procedure. The legal standing to bring a case. In public interest litigation, courts have relaxed this rule so that someone can approach the court for others."}, {"t": "Sub Judice", "u": "glossary.html#term-sub-judice", "k": "Glossary", "d": "Procedure. A matter that is under consideration by a court. Comments that could interfere with a pending case may raise legal concerns."}, {"t": "Ex Parte", "u": "glossary.html#term-ex-parte", "k": "Glossary", "d": "Procedure. A proceeding or order made in the absence of one of the parties, usually because they did not appear after proper notice."}, {"t": "Injunction", "u": "glossary.html#term-injunction", "k": "Glossary", "d": "Civil law. A court order requiring a party to do, or to stop doing, a specific act."}, {"t": "Indemnity", "u": "glossary.html#term-indemnity", "k": "Glossary", "d": "Contract law. A promise to compensate another person for loss. Section 124 of the Indian Contract Act, 1872 defines a contract of indemnity."}, {"t": "Stare Decisis", "u": "glossary.html#term-stare-decisis", "k": "Glossary", "d": "Precedent. The practice of following earlier decisions. In India, Article 141 makes the law declared by the Supreme Court binding on all courts."}, {"t": "Ratio Decidendi", "u": "glossary.html#term-ratio-decidendi", "k": "Glossary", "d": "Precedent. The legal principle on which a decision rests. This is the part of a judgment that carries precedential weight."}, {"t": "Obiter Dicta", "u": "glossary.html#term-obiter-dicta", "k": "Glossary", "d": "Precedent. Remarks in a judgment that were not necessary to decide the case. They can be persuasive but are not binding in the same way as the ratio."}, {"t": "Ultra Vires", "u": "glossary.html#term-ultra-vires", "k": "Glossary", "d": "Constitutional and administrative law. Latin for “beyond the powers”. An action or law that goes beyond the authority given by the Constitution or a statute can be challenged."}, {"t": "Affidavit", "u": "glossary.html#term-affidavit", "k": "Glossary", "d": "Evidence and procedure. A written statement of facts confirmed by oath or affirmation before an authorised officer. It is used as evidence in many proceedings."}, {"t": "Appeal", "u": "glossary.html#term-appeal", "k": "Glossary", "d": "Procedure. A request to a higher court or authority to review and change the decision of a lower one. The right to appeal usually depends on a statute."}, {"t": "Arbitration", "u": "glossary.html#term-arbitration", "k": "Glossary", "d": "Dispute resolution. A private process in which an independent arbitrator decides a dispute under an agreement, instead of a court. In India the Arbitration and Conciliation Act, 1996 governs it."}, {"t": "Caveat Emptor", "u": "glossary.html#term-caveat-emptor", "k": "Glossary", "d": "Contract law. Latin for “let the buyer beware”. The buyer is generally responsible for checking quality, subject to exceptions in laws such as the Sale of Goods Act, 1930."}, {"t": "Certiorari", "u": "glossary.html#term-certiorari", "k": "Glossary", "d": "Constitutional remedy. A writ used to quash a decision of a lower court or tribunal that acted beyond its jurisdiction or made a clear legal error."}, {"t": "Chargesheet", "u": "glossary.html#term-chargesheet", "k": "Glossary", "d": "Criminal procedure. The police report filed in court at the end of an investigation, setting out the evidence and the offences alleged. It is dealt with in Section 193 of the BNSS (earlier Section 173 of the CrPC)."}, {"t": "Decree", "u": "glossary.html#term-decree", "k": "Glossary", "d": "Civil procedure. The formal expression of a court’s decision that conclusively decides the rights of the parties in a suit. Section 2(2) of the Code of Civil Procedure, 1908 defines it."}, {"t": "Estoppel", "u": "glossary.html#term-estoppel", "k": "Glossary", "d": "Evidence. A rule that stops a person from denying something they earlier led another person to believe, when that person acted on it. See Section 115 of the Indian Evidence Act, 1872, and check the corresponding BSA section."}, {"t": "Hearsay", "u": "glossary.html#term-hearsay", "k": "Glossary", "d": "Evidence. A statement made outside court, offered to prove that what it says is true. It is generally not accepted unless an exception applies, because courts prefer direct evidence."}, {"t": "Jurisdiction", "u": "glossary.html#term-jurisdiction", "k": "Glossary", "d": "Procedure. The legal authority of a court to hear and decide a case. It can depend on the subject-matter, the territory and the value of the claim."}, {"t": "Limitation", "u": "glossary.html#term-limitation", "k": "Glossary", "d": "Civil law. A time limit within which a legal action must be started. In India the Limitation Act, 1963 sets different periods for different suits and appeals."}, {"t": "Novation", "u": "glossary.html#term-novation", "k": "Glossary", "d": "Contract law. Replacing an existing contract, or one of its parties, with a new one, with everyone’s consent. Section 62 of the Indian Contract Act, 1872 deals with it."}, {"t": "Perjury", "u": "glossary.html#term-perjury", "k": "Glossary", "d": "Criminal law. Knowingly giving false evidence on oath or when legally bound to tell the truth. It is a criminal offence."}, {"t": "Pro Bono", "u": "glossary.html#term-pro-bono", "k": "Glossary", "d": "Legal practice. Latin for “for the public good”. Legal work done free of charge for people who cannot afford a lawyer."}, {"t": "Prohibition", "u": "glossary.html#term-prohibition", "k": "Glossary", "d": "Constitutional remedy. A writ that stops a lower court or tribunal from continuing a proceeding that it has no jurisdiction to hear."}, {"t": "Quash", "u": "glossary.html#term-quash", "k": "Glossary", "d": "Procedure. To set aside or cancel an order, proceeding or FIR. A High Court may quash an FIR in suitable cases under its inherent powers (Section 528 of the BNSS)."}, {"t": "Quo Warranto", "u": "glossary.html#term-quo-warranto", "k": "Glossary", "d": "Constitutional remedy. A writ meaning “by what authority”. It challenges a person’s right to hold a public office."}, {"t": "Remand", "u": "glossary.html#term-remand", "k": "Glossary", "d": "Criminal procedure. A court order sending an accused to police or judicial custody during investigation or trial. In another sense, an appellate court can send a case back to a lower court."}, {"t": "Review Petition", "u": "glossary.html#term-review-petition", "k": "Glossary", "d": "Procedure. A request asking the same court to re-examine its own judgment, usually on limited grounds such as an error apparent on the face of the record."}, {"t": "Specific Performance", "u": "glossary.html#term-specific-performance", "k": "Glossary", "d": "Contract law. A court order requiring a party to carry out a contract promise instead of paying damages. In India the Specific Relief Act, 1963 governs it."}, {"t": "Tort", "u": "glossary.html#term-tort", "k": "Glossary", "d": "Civil law. A civil wrong, other than a breach of contract, for which the law gives a remedy, usually damages. Examples are negligence and nuisance."}, {"t": "Vicarious Liability", "u": "glossary.html#term-vicarious-liability", "k": "Glossary", "d": "Tort law. Liability of one person for the wrongful act of another, such as an employer for an employee acting in the course of employment."}, {"t": "Waiver", "u": "glossary.html#term-waiver", "k": "Glossary", "d": "Contract law. The voluntary giving up of a known right."}, {"t": "Writ", "u": "glossary.html#term-writ", "k": "Glossary", "d": "Constitutional remedy. A written order issued by a court. The Supreme Court and High Courts can issue writs such as habeas corpus, mandamus, prohibition, certiorari and quo warranto."}, {"t": "Murder: punishment: IPC 302 to BNS 103(1)", "u": "section-finder.html?q=IPC%20302", "k": "Section", "d": "BNS 103(2) adds a provision for murder by a group of five or more persons (mob lynching)."}, {"t": "Attempt to murder: IPC 307 to BNS 109", "u": "section-finder.html?q=IPC%20307", "k": "Section", "d": ""}, {"t": "Culpable homicide not amounting to murder: IPC 304 to BNS 105", "u": "section-finder.html?q=IPC%20304", "k": "Section", "d": ""}, {"t": "Death by negligence: IPC 304A to BNS 106(1)", "u": "section-finder.html?q=IPC%20304A", "k": "Section", "d": ""}, {"t": "Rape: definition: IPC 375 to BNS 63", "u": "section-finder.html?q=IPC%20375", "k": "Section", "d": ""}, {"t": "Rape: punishment: IPC 376 to BNS 64", "u": "section-finder.html?q=IPC%20376", "k": "Section", "d": ""}, {"t": "Dowry death: IPC 304B to BNS 80", "u": "section-finder.html?q=IPC%20304B", "k": "Section", "d": ""}, {"t": "Cruelty by husband or relatives: IPC 498A to BNS 85", "u": "section-finder.html?q=IPC%20498A", "k": "Section", "d": "The meaning of cruelty is now in BNS 86."}, {"t": "Assault to outrage the modesty of a woman: IPC 354 to BNS 74", "u": "section-finder.html?q=IPC%20354", "k": "Section", "d": ""}, {"t": "Sexual harassment: IPC 354A to BNS 75", "u": "section-finder.html?q=IPC%20354A", "k": "Section", "d": ""}, {"t": "Voluntarily causing hurt: IPC 323 to BNS 115(2)", "u": "section-finder.html?q=IPC%20323", "k": "Section", "d": ""}, {"t": "Criminal intimidation: IPC 503 / 506 to BNS 351", "u": "section-finder.html?q=IPC%20503", "k": "Section", "d": ""}, {"t": "Cheating and dishonestly inducing delivery of property: IPC 420 to BNS 318(4)", "u": "section-finder.html?q=IPC%20420", "k": "Section", "d": "Cheating provisions are grouped under BNS 318."}, {"t": "Theft: IPC 378 to BNS 303", "u": "section-finder.html?q=IPC%20378", "k": "Section", "d": "BNS 304 creates a separate offence of snatching."}, {"t": "Defamation: IPC 499 to BNS 356", "u": "section-finder.html?q=IPC%20499", "k": "Section", "d": ""}, {"t": "Common intention: IPC 34 to BNS 3(5)", "u": "section-finder.html?q=IPC%2034", "k": "Section", "d": ""}, {"t": "Criminal conspiracy: IPC 120A / 120B to BNS 61", "u": "section-finder.html?q=IPC%20120A", "k": "Section", "d": ""}, {"t": "Abetment: IPC 107 to BNS 45", "u": "section-finder.html?q=IPC%20107", "k": "Section", "d": ""}, {"t": "Attempt (general provision): IPC 511 to BNS 62", "u": "section-finder.html?q=IPC%20511", "k": "Section", "d": ""}, {"t": "Sedition: IPC 124A to Not carried forward", "u": "section-finder.html?q=IPC%20124A", "k": "Section", "d": "BNS 152 deals with acts endangering the sovereignty, unity and integrity of India. It is a different provision, not a renumbering."}, {"t": "Deceitful promise to marry: No IPC equivalent to BNS 69", "u": "section-finder.html?q=Deceitful%20promise%20to%20marry", "k": "Section", "d": "New specific offence."}, {"t": "Organised crime: No IPC equivalent to BNS 111", "u": "section-finder.html?q=Organised%20crime", "k": "Section", "d": "New offence."}, {"t": "Terrorist act: No IPC equivalent to BNS 113", "u": "section-finder.html?q=Terrorist%20act", "k": "Section", "d": "New offence in the BNS."}, {"t": "Arrest without warrant: CrPC 41 to BNSS 35", "u": "section-finder.html?q=CrPC%2041", "k": "Section", "d": ""}, {"t": "Notice of appearance before police: CrPC 41A to BNSS 35(3)", "u": "section-finder.html?q=CrPC%2041A", "k": "Section", "d": ""}, {"t": "How arrest is made: CrPC 46 to BNSS 43", "u": "section-finder.html?q=CrPC%2046", "k": "Section", "d": ""}, {"t": "Arrested person not to be detained over 24 hours without a magistrate: CrPC 57 to BNSS 58", "u": "section-finder.html?q=CrPC%2057", "k": "Section", "d": ""}, {"t": "Maintenance of wives, children and parents: CrPC 125 to BNSS 144", "u": "section-finder.html?q=CrPC%20125", "k": "Section", "d": ""}, {"t": "FIR: information in cognizable cases: CrPC 154 to BNSS 173", "u": "section-finder.html?q=CrPC%20154", "k": "Section", "d": "Provides for Zero FIR and electronic registration."}, {"t": "Power to require attendance of witnesses: CrPC 160 to BNSS 179", "u": "section-finder.html?q=CrPC%20160", "k": "Section", "d": ""}, {"t": "Examination of witnesses by police: CrPC 161 to BNSS 180", "u": "section-finder.html?q=CrPC%20161", "k": "Section", "d": ""}, {"t": "Recording of confessions before a magistrate: CrPC 164 to BNSS 183", "u": "section-finder.html?q=CrPC%20164", "k": "Section", "d": ""}, {"t": "Detention in custody; default bail: CrPC 167 to BNSS 187", "u": "section-finder.html?q=CrPC%20167", "k": "Section", "d": "Police custody can be spread across phases. The default bail right is preserved."}, {"t": "Police report on completion of investigation: CrPC 173 to BNSS 193", "u": "section-finder.html?q=CrPC%20173", "k": "Section", "d": ""}, {"t": "Cognizance of offences by magistrates: CrPC 190 to BNSS 210", "u": "section-finder.html?q=CrPC%20190", "k": "Section", "d": ""}, {"t": "Examination of complainant: CrPC 200 to BNSS 223", "u": "section-finder.html?q=CrPC%20200", "k": "Section", "d": ""}, {"t": "Summary trials: CrPC 260 to BNSS 283", "u": "section-finder.html?q=CrPC%20260", "k": "Section", "d": ""}, {"t": "Compounding of offences: CrPC 320 to BNSS 359", "u": "section-finder.html?q=CrPC%20320", "k": "Section", "d": ""}, {"t": "Judgment: CrPC 353 to BNSS 392", "u": "section-finder.html?q=CrPC%20353", "k": "Section", "d": ""}, {"t": "Appeal against conviction: CrPC 374 to BNSS 415", "u": "section-finder.html?q=CrPC%20374", "k": "Section", "d": ""}, {"t": "Anticipatory bail: CrPC 438 to BNSS 482", "u": "section-finder.html?q=CrPC%20438", "k": "Section", "d": "BNSS 482 now means anticipatory bail, not inherent powers."}, {"t": "Bail: High Court or Court of Session: CrPC 439 to BNSS 483", "u": "section-finder.html?q=CrPC%20439", "k": "Section", "d": ""}, {"t": "Maximum detention of undertrial prisoners: CrPC 436A to BNSS 479", "u": "section-finder.html?q=CrPC%20436A", "k": "Section", "d": ""}, {"t": "Inherent powers of the High Court: CrPC 482 to BNSS 528", "u": "section-finder.html?q=CrPC%20482", "k": "Section", "d": "Section 482 changed meaning. Do not cite the old number."}, {"t": "Bail in non-bailable offences (Magistrate): CrPC 437 to BNSS 480", "u": "section-finder.html?q=CrPC%20437", "k": "Section", "d": ""}, {"t": "Interpretation clause (definitions): Evidence Act 3 to BSA 2", "u": "section-finder.html?q=Evidence%20Act%203", "k": "Section", "d": ""}, {"t": "Confession to a police officer: Evidence Act 25, 26 to BSA 23(1)", "u": "section-finder.html?q=Evidence%20Act%2025%2C%2026", "k": "Section", "d": "Consolidated in BSA 23 with the discovery provision."}, {"t": "Information leading to discovery: Evidence Act 27 to BSA 23(2)", "u": "section-finder.html?q=Evidence%20Act%2027", "k": "Section", "d": ""}, {"t": "Opinion of experts: Evidence Act 45 to BSA 39", "u": "section-finder.html?q=Evidence%20Act%2045", "k": "Section", "d": ""}, {"t": "Primary evidence: Evidence Act 62 to BSA 57", "u": "section-finder.html?q=Evidence%20Act%2062", "k": "Section", "d": ""}, {"t": "Secondary evidence: Evidence Act 63 to BSA 58", "u": "section-finder.html?q=Evidence%20Act%2063", "k": "Section", "d": ""}, {"t": "Admissibility of electronic records: Evidence Act 65B to BSA 63", "u": "section-finder.html?q=Evidence%20Act%2065B", "k": "Section", "d": "BSA 63 includes a certificate format in a Schedule. Check recent court rulings on its use."}, {"t": "Burden of proving a fact especially within knowledge: Evidence Act 106 to BSA 106", "u": "section-finder.html?q=Evidence%20Act%20106", "k": "Section", "d": "Same number."}, {"t": "Article 12: Definition of “State”", "u": "constitution.html?q=Article%2012", "k": "Constitution", "d": "For Part III, “the State” includes the Government and Parliament, state governments and legislatures, and local and other authorities."}, {"t": "Article 13: Laws inconsistent with Fundamental Rights", "u": "constitution.html?q=Article%2013", "k": "Constitution", "d": "Laws that conflict with Fundamental Rights are void to the extent of the inconsistency."}, {"t": "Article 14: Equality before law", "u": "constitution.html?q=Article%2014", "k": "Constitution", "d": "The State shall not deny any person equality before the law or the equal protection of the laws."}, {"t": "Article 15: Prohibition of discrimination", "u": "constitution.html?q=Article%2015", "k": "Constitution", "d": "No discrimination on grounds only of religion, race, caste, sex or place of birth. Special provisions for women, children and backward classes are permitted."}, {"t": "Article 16: Equality of opportunity in public employment", "u": "constitution.html?q=Article%2016", "k": "Constitution", "d": "Equal opportunity in public jobs, with provision for reservation for backward classes not adequately represented."}, {"t": "Article 17: Abolition of untouchability", "u": "constitution.html?q=Article%2017", "k": "Constitution", "d": "Untouchability is abolished and its practice in any form is forbidden."}, {"t": "Article 18: Abolition of titles", "u": "constitution.html?q=Article%2018", "k": "Constitution", "d": "The State cannot confer titles, apart from military or academic distinctions."}, {"t": "Article 19: Protection of certain freedoms", "u": "constitution.html?q=Article%2019", "k": "Constitution", "d": "Citizens have the freedoms of speech and expression, peaceful assembly, association, movement, residence and practising a profession or business, subject to reasonable restrictions."}, {"t": "Article 20: Protection in respect of conviction for offences", "u": "constitution.html?q=Article%2020", "k": "Constitution", "d": "No retrospective criminal laws, no double jeopardy, and no compulsion to be a witness against oneself."}, {"t": "Article 21: Protection of life and personal liberty", "u": "constitution.html?q=Article%2021", "k": "Constitution", "d": "No person shall be deprived of life or personal liberty except according to procedure established by law. Courts have read in fairness, privacy, livelihood and more."}, {"t": "Article 21A: Right to education", "u": "constitution.html?q=Article%2021A", "k": "Constitution", "d": "Free and compulsory education for children aged six to fourteen."}, {"t": "Article 22: Protection against arrest and detention", "u": "constitution.html?q=Article%2022", "k": "Constitution", "d": "Rights to be told the grounds of arrest, to consult a lawyer, and to be produced before a magistrate within 24 hours. Special rules apply to preventive detention."}, {"t": "Article 23: Prohibition of trafficking and forced labour", "u": "constitution.html?q=Article%2023", "k": "Constitution", "d": "Traffic in human beings and forced labour are prohibited."}, {"t": "Article 24: Prohibition of employment of children", "u": "constitution.html?q=Article%2024", "k": "Constitution", "d": "No child below fourteen may be employed in a factory, mine or other hazardous work."}, {"t": "Article 25: Freedom of religion", "u": "constitution.html?q=Article%2025", "k": "Constitution", "d": "Freedom of conscience and the right to profess, practise and propagate religion, subject to public order, morality and health."}, {"t": "Article 26: Freedom to manage religious affairs", "u": "constitution.html?q=Article%2026", "k": "Constitution", "d": "Religious denominations may manage their own religious affairs and institutions, subject to public order, morality and health."}, {"t": "Article 27: Freedom from taxes for religion", "u": "constitution.html?q=Article%2027", "k": "Constitution", "d": "No one can be compelled to pay taxes for promoting a particular religion."}, {"t": "Article 28: Freedom in religious instruction", "u": "constitution.html?q=Article%2028", "k": "Constitution", "d": "Limits on religious instruction in State-funded educational institutions."}, {"t": "Article 29: Protection of minorities’ interests", "u": "constitution.html?q=Article%2029", "k": "Constitution", "d": "Any section of citizens with a distinct language, script or culture has the right to conserve it."}, {"t": "Article 30: Minorities’ right to educational institutions", "u": "constitution.html?q=Article%2030", "k": "Constitution", "d": "Minorities have the right to establish and administer educational institutions of their choice."}, {"t": "Article 32: Right to constitutional remedies", "u": "constitution.html?q=Article%2032", "k": "Constitution", "d": "The right to move the Supreme Court to enforce Fundamental Rights, including through writs."}, {"t": "Article 36: Definition of “State” in Part IV", "u": "constitution.html?q=Article%2036", "k": "Constitution", "d": "Has the same meaning as in Part III unless the context requires otherwise."}, {"t": "Article 37: Application of Directive Principles", "u": "constitution.html?q=Article%2037", "k": "Constitution", "d": "Directive Principles are not enforceable by courts, but are fundamental in governing the country."}, {"t": "Article 39A: Equal justice and free legal aid", "u": "constitution.html?q=Article%2039A", "k": "Constitution", "d": "The State shall ensure that the legal system promotes justice on the basis of equal opportunity, including free legal aid."}, {"t": "Article 44: Uniform civil code", "u": "constitution.html?q=Article%2044", "k": "Constitution", "d": "The State shall endeavour to secure a uniform civil code for citizens throughout India."}, {"t": "Article 48A: Protection of the environment", "u": "constitution.html?q=Article%2048A", "k": "Constitution", "d": "The State shall endeavour to protect and improve the environment and safeguard forests and wildlife."}, {"t": "Article 50: Separation of judiciary from executive", "u": "constitution.html?q=Article%2050", "k": "Constitution", "d": "The State shall take steps to separate the judiciary from the executive in public services."}, {"t": "Article 51A: Fundamental Duties", "u": "constitution.html?q=Article%2051A", "k": "Constitution", "d": "A list of duties of every citizen, such as respecting the Constitution, protecting the environment and developing scientific temper."}, {"t": "Article 52: The President of India", "u": "constitution.html?q=Article%2052", "k": "Constitution", "d": "There shall be a President of India."}, {"t": "Article 53: Executive power of the Union", "u": "constitution.html?q=Article%2053", "k": "Constitution", "d": "The executive power of the Union is vested in the President."}, {"t": "Article 72: Power of the President to grant pardons", "u": "constitution.html?q=Article%2072", "k": "Constitution", "d": "The President may grant pardons, reprieves, respites or remissions of punishment and suspend, remit or commute sentences in specified cases."}, {"t": "Article 74: Council of Ministers to aid and advise President", "u": "constitution.html?q=Article%2074", "k": "Constitution", "d": "There shall be a Council of Ministers with the Prime Minister at the head to aid and advise the President."}, {"t": "Article 79: Constitution of Parliament", "u": "constitution.html?q=Article%2079", "k": "Constitution", "d": "Parliament consists of the President and the two Houses: the Council of States and the House of the People."}, {"t": "Article 123: Power of the President to promulgate ordinances", "u": "constitution.html?q=Article%20123", "k": "Constitution", "d": "The President can issue ordinances when Parliament is not in session, if circumstances require immediate action."}, {"t": "Article 124: Establishment of the Supreme Court", "u": "constitution.html?q=Article%20124", "k": "Constitution", "d": "Provides for the Supreme Court of India and its judges."}, {"t": "Article 129: Supreme Court as a court of record", "u": "constitution.html?q=Article%20129", "k": "Constitution", "d": "The Supreme Court is a court of record with power to punish for contempt of itself."}, {"t": "Article 131: Original jurisdiction of the Supreme Court", "u": "constitution.html?q=Article%20131", "k": "Constitution", "d": "The Supreme Court decides certain disputes between the Union and States, or between States, in its original jurisdiction."}, {"t": "Article 136: Special leave to appeal", "u": "constitution.html?q=Article%20136", "k": "Constitution", "d": "The Supreme Court may grant special leave to appeal from almost any court or tribunal in India."}, {"t": "Article 141: Law declared by the Supreme Court", "u": "constitution.html?q=Article%20141", "k": "Constitution", "d": "The law declared by the Supreme Court is binding on all courts in India."}, {"t": "Article 142: Enforcement of decrees and orders", "u": "constitution.html?q=Article%20142", "k": "Constitution", "d": "The Supreme Court can pass such orders as are necessary to do complete justice in a case."}, {"t": "Article 143: Power of the President to consult the Supreme Court", "u": "constitution.html?q=Article%20143", "k": "Constitution", "d": "The President may seek the Supreme Court’s advisory opinion on a question of law or fact."}, {"t": "Article 161: Power of the Governor to grant pardons", "u": "constitution.html?q=Article%20161", "k": "Constitution", "d": "The Governor may grant pardons and similar relief in matters within the State’s executive power."}, {"t": "Article 213: Power of the Governor to promulgate ordinances", "u": "constitution.html?q=Article%20213", "k": "Constitution", "d": "The Governor can issue ordinances when the State Legislature is not in session."}, {"t": "Article 214: High Courts for States", "u": "constitution.html?q=Article%20214", "k": "Constitution", "d": "There shall be a High Court for each State."}, {"t": "Article 215: High Courts as courts of record", "u": "constitution.html?q=Article%20215", "k": "Constitution", "d": "High Courts are courts of record and can punish for contempt of themselves."}, {"t": "Article 226: Power of High Courts to issue writs", "u": "constitution.html?q=Article%20226", "k": "Constitution", "d": "High Courts can issue writs to enforce Fundamental Rights and for any other purpose."}, {"t": "Article 227: Superintendence over courts", "u": "constitution.html?q=Article%20227", "k": "Constitution", "d": "Every High Court has superintendence over all courts and tribunals in its territory."}, {"t": "Article 245: Extent of laws made by Parliament and States", "u": "constitution.html?q=Article%20245", "k": "Constitution", "d": "Parliament and State Legislatures make laws for their territories, subject to the Constitution."}, {"t": "Article 246: Subject-matter of laws", "u": "constitution.html?q=Article%20246", "k": "Constitution", "d": "Divides legislative subjects among the Union, State and Concurrent Lists in the Seventh Schedule."}, {"t": "Article 300A: Persons not to be deprived of property save by law", "u": "constitution.html?q=Article%20300A", "k": "Constitution", "d": "No person shall be deprived of property except by authority of law. This is a constitutional right, not a Fundamental Right."}, {"t": "Article 324: Election Commission", "u": "constitution.html?q=Article%20324", "k": "Constitution", "d": "Superintendence, direction and control of elections is vested in the Election Commission."}, {"t": "Article 326: Adult suffrage", "u": "constitution.html?q=Article%20326", "k": "Constitution", "d": "Elections to the House of the People and State Assemblies are on the basis of adult suffrage."}, {"t": "Article 352: Proclamation of Emergency", "u": "constitution.html?q=Article%20352", "k": "Constitution", "d": "The President can proclaim an Emergency on grounds such as war, external aggression or armed rebellion, subject to conditions."}, {"t": "Article 356: Failure of constitutional machinery in States", "u": "constitution.html?q=Article%20356", "k": "Constitution", "d": "Provides for President’s Rule in a State. The power is subject to judicial review (S.R. Bommai)."}, {"t": "Article 360: Financial Emergency", "u": "constitution.html?q=Article%20360", "k": "Constitution", "d": "Provides for a Financial Emergency if the financial stability or credit of India is threatened."}, {"t": "Article 368: Power of Parliament to amend the Constitution", "u": "constitution.html?q=Article%20368", "k": "Constitution", "d": "Parliament may amend the Constitution, but not its basic structure (Kesavananda Bharati)."}, {"t": "Old-to-new section finder", "u": "section-finder.html", "k": "Guide", "d": "IPC to BNS, CrPC to BNSS, Evidence Act to BSA"}, {"t": "Quiz bank", "u": "quiz.html", "k": "Guide", "d": "Subject-wise law quizzes"}, {"t": "Moot court corner", "u": "moot.html", "k": "Guide", "d": "Memorials, issues and oral advocacy"}, {"t": "Drafting practice", "u": "drafting.html", "k": "Guide", "d": "Legal notice, petition, RTI, contract clauses"}, {"t": "Careers and internships", "u": "careers.html", "k": "Guide", "d": "Internships, CV, interviews"}, {"t": "Know your rights", "u": "know-your-rights.html", "k": "Guide", "d": "Arrest, FIR, consumer complaint, legal aid"}, {"t": "Law exam hub", "u": "exam-hub.html", "k": "Guide", "d": "CLAT, AIBE, judicial services, UGC-NET"}, {"t": "Citation generator", "u": "cite-it.html", "k": "Guide", "d": "Format case and statute citations"}, {"t": "Browse by topic", "u": "topics.html", "k": "Guide", "d": "All content by area of law"}, {"t": "Decision Room", "u": "decision-room.html", "k": "Guide", "d": "Scenario practice"}, {"t": "About Legal Lounge Live", "u": "about.html", "k": "Guide", "d": "Mission and editorial standards"}, {"t": "Bail and anticipatory bail: what students should know", "u": "article-bail.html", "k": "Article", "d": "What bail is, the main types, the principles courts apply, and where the provisions now sit in the BNSS."}, {"t": "Cheque bounce: how Section 138 of the NI Act works", "u": "article-cheque-bounce.html", "k": "Article", "d": "The steps, time limits and basic ideas behind a cheque dishonour case in India."}, {"t": "The five writs: what each one does", "u": "article-writs.html", "k": "Article", "d": "Habeas corpus, mandamus, prohibition, certiorari and quo warranto, with the Articles under which they are issued."}, {"t": "How to read a bare Act", "u": "article-read-a-bare-act.html", "k": "Article", "d": "A short method for reading a statute without getting lost: structure, definitions, provisos and amendments."}, {"t": "Contract Act Section 2(a): Proposal", "u": "bare-acts.html?q=Section%202%28a%29", "k": "Bare Act", "d": "One person shows willingness to do or not do something in order to get the other’s assent."}, {"t": "Contract Act Section 2(b): Promise", "u": "bare-acts.html?q=Section%202%28b%29", "k": "Bare Act", "d": "A proposal, when accepted, becomes a promise."}, {"t": "Contract Act Section 2(d): Consideration", "u": "bare-acts.html?q=Section%202%28d%29", "k": "Bare Act", "d": "Something done, not done, or promised at the promisor’s desire, by the promisee or any other person."}, {"t": "Contract Act Section 2(e): Agreement", "u": "bare-acts.html?q=Section%202%28e%29", "k": "Bare Act", "d": "Every promise and every set of promises that form the consideration for each other."}, {"t": "Contract Act Section 2(g): Void agreement", "u": "bare-acts.html?q=Section%202%28g%29", "k": "Bare Act", "d": "An agreement that is not enforceable by law."}, {"t": "Contract Act Section 2(h): Contract", "u": "bare-acts.html?q=Section%202%28h%29", "k": "Bare Act", "d": "An agreement that is enforceable by law."}, {"t": "Contract Act Section 2(i): Voidable contract", "u": "bare-acts.html?q=Section%202%28i%29", "k": "Bare Act", "d": "A contract enforceable at the option of one or more of the parties, but not of the other or others."}, {"t": "Contract Act Section 10: What agreements are contracts", "u": "bare-acts.html?q=Section%2010", "k": "Bare Act", "d": "Agreements made with free consent, by competent parties, for a lawful consideration and object, and not expressly declared void."}, {"t": "Contract Act Section 11: Who is competent to contract", "u": "bare-acts.html?q=Section%2011", "k": "Bare Act", "d": "A person who is of the age of majority, of sound mind and not disqualified by law."}, {"t": "Contract Act Section 14: Free consent", "u": "bare-acts.html?q=Section%2014", "k": "Bare Act", "d": "Consent is free when it is not caused by coercion, undue influence, fraud, misrepresentation or mistake."}, {"t": "Contract Act Section 15: Coercion", "u": "bare-acts.html?q=Section%2015", "k": "Bare Act", "d": "Committing or threatening an act forbidden by law, or unlawfully detaining property, to make a person agree."}, {"t": "Contract Act Section 16: Undue influence", "u": "bare-acts.html?q=Section%2016", "k": "Bare Act", "d": "One party can dominate the other’s will and uses that position to obtain an unfair advantage."}, {"t": "Contract Act Section 17: Fraud", "u": "bare-acts.html?q=Section%2017", "k": "Bare Act", "d": "Deceiving a party to induce a contract, for example by a knowingly false statement or by active concealment."}, {"t": "Contract Act Section 18: Misrepresentation", "u": "bare-acts.html?q=Section%2018", "k": "Bare Act", "d": "A false statement made innocently, or without reasonable grounds, that misleads the other party."}, {"t": "Contract Act Section 19, 19A: Voidability where consent is not free", "u": "bare-acts.html?q=19", "k": "Bare Act", "d": "A contract caused by coercion, fraud or misrepresentation (Section 19) or undue influence (Section 19A) is voidable at the option of the affected party."}, {"t": "Contract Act Section 23: Lawful consideration and object", "u": "bare-acts.html?q=Section%2023", "k": "Bare Act", "d": "Unlawful if forbidden by law, defeats a law, is fraudulent, injures a person or property, or is immoral or against public policy."}, {"t": "Contract Act Section 25: Agreement without consideration", "u": "bare-acts.html?q=Section%2025", "k": "Bare Act", "d": "Void, with exceptions such as a written and registered agreement made out of natural love and affection, or a promise to pay a time-barred debt."}, {"t": "Contract Act Section 27: Restraint of trade", "u": "bare-acts.html?q=Section%2027", "k": "Bare Act", "d": "An agreement that restrains a person from carrying on a lawful profession, trade or business is void, subject to limited exceptions."}, {"t": "Contract Act Section 30: Wager agreements", "u": "bare-acts.html?q=Section%2030", "k": "Bare Act", "d": "Agreements by way of wager are void."}, {"t": "Contract Act Section 56: Impossible acts", "u": "bare-acts.html?q=Section%2056", "k": "Bare Act", "d": "An agreement to do an impossible act is void. A contract becomes void if the act later becomes impossible or unlawful."}, {"t": "Contract Act Section 62: Novation", "u": "bare-acts.html?q=Section%2062", "k": "Bare Act", "d": "The parties may replace a contract with a new one, or alter or rescind it."}, {"t": "Contract Act Section 73: Compensation for breach", "u": "bare-acts.html?q=Section%2073", "k": "Bare Act", "d": "The party who suffers a breach can claim compensation for loss that arose naturally or was in the parties’ contemplation. Remote loss is not covered."}, {"t": "Contract Act Section 74: Named sum or penalty on breach", "u": "bare-acts.html?q=Section%2074", "k": "Bare Act", "d": "Where a sum is named as payable on breach, the party may receive reasonable compensation not exceeding that sum."}, {"t": "Contract Act Section 124, 126: Indemnity and guarantee", "u": "bare-acts.html?q=124", "k": "Bare Act", "d": "Indemnity is a promise to protect against loss (Section 124). A guarantee is a promise to perform, or discharge the liability of, a third person if they default (Section 126)."}, {"t": "RTI Act Section 3: Right to information", "u": "bare-acts.html?q=Section%203", "k": "Bare Act", "d": "Subject to the Act, all citizens have the right to information."}, {"t": "RTI Act Section 4: Obligations of public authorities", "u": "bare-acts.html?q=Section%204", "k": "Bare Act", "d": "Public authorities must maintain records and proactively disclose certain information."}, {"t": "RTI Act Section 5: Public Information Officers", "u": "bare-acts.html?q=Section%205", "k": "Bare Act", "d": "Public authorities designate officers to receive and process requests."}, {"t": "RTI Act Section 6: Making a request", "u": "bare-acts.html?q=Section%206", "k": "Bare Act", "d": "Apply in writing or electronically with the prescribed fee. The applicant does not have to give a reason (Section 6(2))."}, {"t": "RTI Act Section 7: Disposal of a request", "u": "bare-acts.html?q=Section%207", "k": "Bare Act", "d": "A decision is generally due within 30 days, or within 48 hours where the life or liberty of a person is involved."}, {"t": "RTI Act Section 8: Exemptions", "u": "bare-acts.html?q=Section%208", "k": "Bare Act", "d": "Lists information that may be refused, such as matters affecting sovereignty and security. Some exemptions are subject to a public interest test (Section 8(2))."}, {"t": "RTI Act Section 11: Third-party information", "u": "bare-acts.html?q=Section%2011", "k": "Bare Act", "d": "Sets the procedure when the information relates to or was supplied by a third party."}, {"t": "RTI Act Section 18: Complaints", "u": "bare-acts.html?q=Section%2018", "k": "Bare Act", "d": "A person can complain to the Information Commission about certain failures of the authority."}, {"t": "RTI Act Section 19: Appeals", "u": "bare-acts.html?q=Section%2019", "k": "Bare Act", "d": "A first appeal goes to a senior officer within the authority (generally within 30 days). A second appeal goes to the Information Commission (generally within 90 days)."}, {"t": "RTI Act Section 20: Penalties", "u": "bare-acts.html?q=Section%2020", "k": "Bare Act", "d": "The Information Commission can impose penalties on a Public Information Officer in specified cases."}, {"t": "RTI Act Section 22: Overriding effect", "u": "bare-acts.html?q=Section%2022", "k": "Bare Act", "d": "The Act has effect despite inconsistent provisions in other laws, such as the Official Secrets Act, 1923."}, {"t": "Consumer Protection Act Section 2(7): Consumer", "u": "bare-acts.html?q=Section%202%287%29", "k": "Bare Act", "d": "A person who buys goods or hires or avails services for consideration, generally excluding those who buy for resale or commercial purposes."}, {"t": "Consumer Protection Act Section 2(9): Consumer rights", "u": "bare-acts.html?q=Section%202%289%29", "k": "Bare Act", "d": "The rights to safety, information, choice, being heard, seeking redress and consumer awareness."}, {"t": "Consumer Protection Act Section 2(10): Defect", "u": "bare-acts.html?q=Section%202%2810%29", "k": "Bare Act", "d": "Any fault or imperfection in the quality, quantity, potency, purity or standard of goods."}, {"t": "Consumer Protection Act Section 2(11): Deficiency", "u": "bare-acts.html?q=Section%202%2811%29", "k": "Bare Act", "d": "Any fault or shortcoming in the quality, nature or manner of performance of a service."}, {"t": "Consumer Protection Act Section 2(47): Unfair trade practice", "u": "bare-acts.html?q=Section%202%2847%29", "k": "Bare Act", "d": "An unfair or deceptive practice, such as a false representation or a misleading advertisement, in promoting the sale or supply of goods or services."}, {"t": "Consumer Protection Act Section 10: Central Consumer Protection Authority", "u": "bare-acts.html?q=Section%2010", "k": "Bare Act", "d": "Established to protect, promote and enforce consumer rights, including action against misleading advertisements."}, {"t": "Consumer Protection Act Section 35: Filing a complaint", "u": "bare-acts.html?q=Section%2035", "k": "Bare Act", "d": "A complaint is made to the District Commission, and it can be filed electronically."}, {"t": "Consumer Protection Act Section 69: Limitation", "u": "bare-acts.html?q=Section%2069", "k": "Bare Act", "d": "A complaint should generally be filed within two years from the date the cause of action arose. Delay can be condoned for sufficient reasons."}, {"t": "Consumer Protection Act Section 82 to 87: Product liability", "u": "bare-acts.html?q=82", "k": "Bare Act", "d": "Manufacturers, sellers and service providers can be liable for harm caused by defective products or deficient services, subject to the conditions in the Act."}, {"t": "1st Constitutional Amendment (1951)", "u": "amendments.html?q=1st", "k": "Amendment", "d": "Added the Ninth Schedule and Articles 31A and 31B, added Article 15(4), and widened the restrictions on free speech in Article 19(2)."}, {"t": "7th Constitutional Amendment (1956)", "u": "amendments.html?q=7th", "k": "Amendment", "d": "Reorganised States largely on linguistic lines and did away with the Part A, B, C and D categories of States."}, {"t": "24th Constitutional Amendment (1971)", "u": "amendments.html?q=24th", "k": "Amendment", "d": "Affirmed Parliament’s power to amend Fundamental Rights. Kesavananda Bharati later placed the basic structure limit on this power."}, {"t": "25th Constitutional Amendment (1971)", "u": "amendments.html?q=25th", "k": "Amendment", "d": "Limited the right to property compensation and added Article 31C."}, {"t": "42nd Constitutional Amendment (1976)", "u": "amendments.html?q=42nd", "k": "Amendment", "d": "Wide-ranging changes. Added “socialist”, “secular” and “integrity” to the Preamble and added Fundamental Duties (Part IVA). Parts were struck down in Minerva Mills."}, {"t": "44th Constitutional Amendment (1978)", "u": "amendments.html?q=44th", "k": "Amendment", "d": "Removed the right to property from Fundamental Rights (now Article 300A) and added safeguards on the Emergency, including that Articles 20 and 21 cannot be suspended."}, {"t": "52nd Constitutional Amendment (1985)", "u": "amendments.html?q=52nd", "k": "Amendment", "d": "Added the Tenth Schedule, the anti-defection law."}, {"t": "61st Constitutional Amendment (1988)", "u": "amendments.html?q=61st", "k": "Amendment", "d": "Lowered the voting age from 21 to 18 years."}, {"t": "73rd Constitutional Amendment (1992)", "u": "amendments.html?q=73rd", "k": "Amendment", "d": "Gave constitutional status to Panchayati Raj institutions (Part IX)."}, {"t": "74th Constitutional Amendment (1992)", "u": "amendments.html?q=74th", "k": "Amendment", "d": "Gave constitutional status to urban local bodies (Part IXA)."}, {"t": "86th Constitutional Amendment (2002)", "u": "amendments.html?q=86th", "k": "Amendment", "d": "Inserted Article 21A, the right to education for children aged six to fourteen."}, {"t": "99th Constitutional Amendment (2014)", "u": "amendments.html?q=99th", "k": "Amendment", "d": "Created the National Judicial Appointments Commission. The Supreme Court struck it down in 2015 (reported at (2016) 5 SCC 1)."}, {"t": "101st Constitutional Amendment (2016)", "u": "amendments.html?q=101st", "k": "Amendment", "d": "Introduced the Goods and Services Tax."}, {"t": "103rd Constitutional Amendment (2019)", "u": "amendments.html?q=103rd", "k": "Amendment", "d": "Provided reservation for economically weaker sections (Articles 15(6) and 16(6))."}, {"t": "106th Constitutional Amendment (2023)", "u": "amendments.html?q=106th", "k": "Amendment", "d": "Women’s reservation: one-third of seats for women in the Lok Sabha and State Legislative Assemblies, to take effect after the relevant census and delimitation."}, {"t": "Actus non facit reum nisi mens sit rea", "u": "maxims.html#maxim-actus-non-facit-reum-nisi-mens-sit-rea", "k": "Maxim", "d": "An act does not make a person guilty unless the mind is also guilty. Most offences need a guilty act and a guilty mind."}, {"t": "Audi alteram partem", "u": "maxims.html#maxim-audi-alteram-partem", "k": "Maxim", "d": "Hear the other side. A person must get a fair chance to be heard before an adverse order is made."}, {"t": "Caveat emptor", "u": "maxims.html#maxim-caveat-emptor", "k": "Maxim", "d": "Let the buyer beware. A buyer must inspect goods, subject to statutory protections."}, {"t": "De minimis non curat lex", "u": "maxims.html#maxim-de-minimis-non-curat-lex", "k": "Maxim", "d": "The law does not concern itself with trifles. A very small harm may not justify legal action."}, {"t": "Damnum sine injuria", "u": "maxims.html#maxim-damnum-sine-injuria", "k": "Maxim", "d": "Damage without a legal wrong. Loss from lawful competition gives no claim."}, {"t": "Ejusdem generis", "u": "maxims.html#maxim-ejusdem-generis", "k": "Maxim", "d": "Of the same kind. General words after a list are read as limited to things of the same kind."}, {"t": "Expressio unius est exclusio alterius", "u": "maxims.html#maxim-expressio-unius-est-exclusio-alterius", "k": "Maxim", "d": "The mention of one thing excludes others. If a statute lists specific items, others may be left out."}, {"t": "Ignorantia juris non excusat", "u": "maxims.html#maxim-ignorantia-juris-non-excusat", "k": "Maxim", "d": "Ignorance of the law is no excuse. A person cannot avoid liability by saying they did not know the law."}, {"t": "Injuria sine damno", "u": "maxims.html#maxim-injuria-sine-damno", "k": "Maxim", "d": "A legal wrong without actual loss. A violation of a legal right can be actionable even without proof of loss."}, {"t": "Nemo dat quod non habet", "u": "maxims.html#maxim-nemo-dat-quod-non-habet", "k": "Maxim", "d": "No one gives what they do not have. A seller generally cannot pass a better title than their own."}, {"t": "Nemo debet bis vexari pro una et eadem causa", "u": "maxims.html#maxim-nemo-debet-bis-vexari-pro-una-et-eadem-causa", "k": "Maxim", "d": "No one should be troubled twice for the same cause. The idea behind double jeopardy, protected by Article 20(2)."}, {"t": "Nemo judex in causa sua", "u": "maxims.html#maxim-nemo-judex-in-causa-sua", "k": "Maxim", "d": "No one should be a judge in their own cause. The rule against bias."}, {"t": "Noscitur a sociis", "u": "maxims.html#maxim-noscitur-a-sociis", "k": "Maxim", "d": "A word is known by the company it keeps. The meaning of an unclear word is taken from the words around it."}, {"t": "Obiter dicta", "u": "maxims.html#maxim-obiter-dicta", "k": "Maxim", "d": "Things said in passing. Remarks in a judgment that are not necessary for the decision. They are persuasive, not binding."}, {"t": "Pacta sunt servanda", "u": "maxims.html#maxim-pacta-sunt-servanda", "k": "Maxim", "d": "Agreements must be kept. The basic principle that promises should be honoured."}, {"t": "Per incuriam", "u": "maxims.html#maxim-per-incuriam", "k": "Maxim", "d": "Through lack of care. A decision made without noticing a binding authority or statute may lose its precedent value."}, {"t": "Ratio decidendi", "u": "maxims.html#maxim-ratio-decidendi", "k": "Maxim", "d": "The reason for the decision. The legal principle on which a decision rests."}, {"t": "Res ipsa loquitur", "u": "maxims.html#maxim-res-ipsa-loquitur", "k": "Maxim", "d": "The thing speaks for itself. In some negligence cases the accident itself suggests negligence."}, {"t": "Res judicata", "u": "maxims.html#maxim-res-judicata", "k": "Maxim", "d": "A matter already judged. A matter finally decided between the same parties cannot be re-opened."}, {"t": "Respondeat superior", "u": "maxims.html#maxim-respondeat-superior", "k": "Maxim", "d": "Let the superior answer. The basis of vicarious liability of an employer for an employee."}, {"t": "Stare decisis", "u": "maxims.html#maxim-stare-decisis", "k": "Maxim", "d": "To stand by what has been decided. Courts follow earlier decisions. Under Article 141, Supreme Court law binds all courts."}, {"t": "Sub judice", "u": "maxims.html#maxim-sub-judice", "k": "Maxim", "d": "Under judicial consideration. A matter pending before a court."}, {"t": "Ubi jus ibi remedium", "u": "maxims.html#maxim-ubi-jus-ibi-remedium", "k": "Maxim", "d": "Where there is a right, there is a remedy. A legal right should have a legal remedy."}, {"t": "Ultra vires", "u": "maxims.html#maxim-ultra-vires", "k": "Maxim", "d": "Beyond the powers. An act beyond the authority given by law can be challenged."}, {"t": "Vigilantibus non dormientibus jura subveniunt", "u": "maxims.html#maxim-vigilantibus-non-dormientibus-jura-subveniunt", "k": "Maxim", "d": "The law helps those who are vigilant, not those who sleep on their rights. The idea behind limitation periods."}, {"t": "Volenti non fit injuria", "u": "maxims.html#maxim-volenti-non-fit-injuria", "k": "Maxim", "d": "No wrong is done to one who consents. Consent to a risk can be a defence in tort, subject to limits."}, {"t": "Cheat sheet: old to new criminal laws", "u": "cheatsheets.html", "k": "Guide", "d": "printable"}, {"t": "Cheat sheet: Fundamental Rights", "u": "cheatsheets.html", "k": "Guide", "d": "printable"}, {"t": "Cheat sheet: the five writs", "u": "cheatsheets.html", "k": "Guide", "d": "printable"}, {"t": "अपने अधिकार जानें (हिन्दी)", "u": "know-your-rights-hi.html", "k": "Guide", "d": "गिरफ्तारी, एफ़आईआर, उपभोक्ता शिकायत और मुफ़्त कानूनी सहायता"}, {"t": "Timed mock test", "u": "mock-test.html", "k": "Guide", "d": "20 questions in 20 minutes"}, {"t": "Case flashcards", "u": "case-flashcards.html", "k": "Guide", "d": "Revise landmark cases"}, {"t": "Decision flows", "u": "decision-flows.html", "k": "Guide", "d": "Which writ, valid contract"}, {"t": "My study", "u": "my-study.html", "k": "Guide", "d": "Saved items and scores"}, {"t": "Newsletter", "u": "newsletter.html", "k": "Guide", "d": "Email updates"}, {"t": "Events", "u": "events.html", "k": "Guide", "d": "Live sessions"}, {"t": "Write for Legal Lounge Live", "u": "contribute.html", "k": "Guide", "d": "Guest articles"}, {"t": "Corrections and updates", "u": "corrections.html", "k": "Guide", "d": "Corrections log"}, {"t": "All resources", "u": "resources.html", "k": "Guide", "d": "Everything in one place"}, {"t": "Bare Act summaries", "u": "bare-acts.html", "k": "Guide", "d": "Contract Act, RTI Act, Consumer Protection Act"}, {"t": "Constitutional amendments timeline", "u": "amendments.html", "k": "Guide", "d": "Major amendments"}, {"t": "Legal maxims A to Z", "u": "maxims.html", "k": "Guide", "d": "Latin maxims"}, {"t": "Printable cheat sheets", "u": "cheatsheets.html", "k": "Guide", "d": "Print or save as PDF"}];